-- Proxima warmup exercise templates (WU*) for local development.
-- Source: production hevy_exercise_templates WHERE id LIKE 'WU%'.
-- Not available from the Hevy API - apply after Hevy library seed in start-local-supabase.sh.

INSERT INTO public.hevy_exercise_templates (
    id,
    title,
    type,
    primary_muscle_group,
    secondary_muscle_groups,
    is_custom,
    equipment,
    normalized_title,
    gif_id,
    instructions
) VALUES
('WU000001','Jumping Jacks','duration','full_body',NULL,true,'none','jacks jumping','5203',ARRAY['Stand with feet together and arms at your sides.','Jump both feet out to shoulder-width while simultaneously raising both arms overhead.','Jump both feet back together while lowering arms back to your sides.','Maintain a steady rhythm and land softly on the balls of your feet.','Keep your core lightly engaged and your gaze forward throughout.','Perform continuously for the prescribed duration, breathing rhythmically.']::text[]),
('WU000003','Butt Kicks','duration','quadriceps',ARRAY['hamstrings']::text[],true,'none','butt kicks','5204',ARRAY['Stand tall with feet hip-width apart, looking straight ahead.','Begin jogging lightly in place on the balls of your feet.','Kick your right heel back toward your right glute, squeezing the hamstring at the top.','Alternate legs quickly, kicking each heel up toward the corresponding glute.','Keep your knees pointing down and your thighs relatively still.','Maintain an upright posture and swing your arms naturally to aid rhythm.']::text[]),
('WU000004','Inchworm Walk-Out','reps_only','hamstrings',ARRAY['lower_back','shoulders']::text[],true,'none','inchworm walkout','5207',ARRAY['Stand with feet hip-width apart, arms at your sides.','Hinge forward at the hips, placing both hands on the floor in front of your feet.','Walk your hands forward one at a time until you reach a high plank position with a straight body.','Pause briefly in the plank, then walk your hands back toward your feet one at a time.','Once hands reach feet, hinge at the hips and return to standing.','Perform slowly and with control, keeping legs as straight as flexibility allows.']::text[]),
('WU000005','World''s Greatest Stretch','reps_only','full_body',ARRAY['hamstrings','glutes','shoulders']::text[],true,'none','greatest stretch worlds','5206',ARRAY['Stand with feet hip-width apart and step your right foot forward into a deep lunge.','Plant your right hand on the floor inside your right foot for support.','Rotate your left arm upward toward the ceiling, following it with your eyes, to open the thoracic spine.','Return your left hand to the floor, then press your right elbow gently against your inner knee to deepen the hip stretch.','Straighten your right leg slightly and reach your right hand toward the sky for a hamstring stretch.','Return to the lunge position, step back to standing, and repeat on the left side.']::text[]),
('WU000006','Bear Crawl','duration','full_body',ARRAY['shoulders','abdominals']::text[],true,'none','bear crawl','5211',ARRAY['Begin on all fours with wrists under shoulders and knees under hips.','Lift your knees one to two inches off the floor, keeping your back flat and core tight.','Move your right hand and left knee forward simultaneously by a few inches.','Follow with your left hand and right knee, maintaining the hovering position.','Keep your hips low and level, avoiding any rocking side to side.','Continue crawling forward for the prescribed distance or time, then reverse direction.']::text[]),
('WU000007','Jumping Rope','duration','full_body',ARRAY['quadriceps','shoulders']::text[],true,'none','jumping rope','5212',ARRAY['Hold the rope handles with one handle in each hand, rope behind you.','Swing the rope overhead and jump with both feet as it passes underneath.','Land softly on the balls of both feet with a slight bend in the knees.','Keep your elbows close to your sides and use small wrist circles to turn the rope.','Maintain an upright posture with eyes forward and core lightly braced.','Find a steady cadence and breathe rhythmically for the full prescribed duration.']::text[]),
('WU000008','Arm Swings','reps_only','shoulders',ARRAY['chest','upper_back']::text[],true,'none','arm swings','5208',ARRAY['Stand with feet hip-width apart, arms extended straight out to each side at shoulder height.','Sweep both arms forward across your chest, allowing them to cross, keeping them at shoulder height.','Immediately swing both arms back as far as comfortable, squeezing the shoulder blades together.','Keep a slight bend in the elbows throughout to protect the joints.','Perform each repetition in a controlled, fluid motion without jerking.','Gradually increase the range of motion as your shoulders warm up.']::text[]),
('WU000009','Hip Circles','reps_only','glutes',ARRAY['lower_back']::text[],true,'none','hip circles','5202',ARRAY['Stand with feet hip-width apart, hands resting on your hips for balance.','Shift your weight to your left leg and lift your right foot slightly off the floor.','Draw large, slow circles with your right hip, rotating it forward, out, back, and around.','Complete the prescribed number of circles in one direction, then reverse the direction.','Keep your upper body relatively still and your core gently engaged.','Switch legs and repeat the same number of circles on the left side.']::text[]),
('WU000010','Lateral Shuffle','duration','full_body',ARRAY['quadriceps','glutes']::text[],true,'none','lateral shuffle','5209',ARRAY['Stand in an athletic stance with knees slightly bent, weight on the balls of your feet.','Push off your right foot to step your left foot to the left.','Bring your right foot to meet your left, then immediately step your left foot out again.','Continue shuffling laterally for several meters, then reverse direction.','Stay low throughout, keeping your hips back and chest up.','Move smoothly and quickly without crossing your feet.']::text[]),
('WU000011','Cat-Cow Stretch','reps_only','lower_back',ARRAY['abdominals','upper_back']::text[],true,'none','catcow stretch','5205',ARRAY['Start on all fours with wrists under shoulders and knees under hips.','For Cat: exhale and round your entire spine upward toward the ceiling, tucking your chin to your chest and tailbone under.','Hold the rounded position for a breath, feeling a stretch across the entire back.','For Cow: inhale and let your belly drop toward the floor, lifting your head and tailbone toward the ceiling.','Hold the extended position for a breath, feeling a stretch through the abdominals.','Flow slowly between Cat and Cow, linking each movement to an inhale or exhale.']::text[]),
('WU000013','Quadruped Bird Dog','reps_only','abdominals',ARRAY['glutes','lower_back','shoulders']::text[],true,'none','bird dog quadruped',NULL,ARRAY['Begin on all fours with a neutral spine, wrists under shoulders, knees under hips.','Brace your core to prevent the spine from rotating or sagging.','Simultaneously extend your right arm straight forward and your left leg straight back.','Hold briefly at the top, keeping your hips level and back flat.','Return the hand and knee slowly to the floor under control.','Alternate sides, extending the left arm and right leg next, and continue for all prescribed reps.']::text[]),
('WU000015','Hip 90/90 Stretch','duration','glutes',ARRAY['hamstrings']::text[],true,'none','hip 9090 stretch','5217',ARRAY['Sit on the floor and bend both knees to 90 degrees, one leg in front of you and one to the side - forming two right angles.','Sit tall with your hands lightly on the floor behind you for support.','Hold the position, feeling a stretch in the glute of your front leg and the hip flexor of your back leg.','To deepen the stretch, gently fold your torso forward over your front shin.','After the prescribed time, use your hands to lift your knees and rotate them to the opposite side to switch.','Repeat the hold on the second side for the same duration.']::text[]),
('WU000016','Prone Press-Up (McKenzie Extension)','reps_only','lower_back',NULL,true,'none','extension mckenzie pressup prone',NULL,ARRAY['Lie face down on the floor with your legs straight and your hands placed flat under your shoulders.','Keep your hips and legs relaxed against the floor throughout the movement.','Gently press through your hands to extend your elbows, lifting your chest off the floor.','Go only as far as comfortable - even a small range of motion is beneficial.','Hold at the top for a breath without tensing the glutes or legs.','Lower back down slowly and repeat for the prescribed number of reps.']::text[]),
('WU000017','Standing Hip Hinge','reps_only','hamstrings',ARRAY['glutes','lower_back']::text[],true,'none','hinge hip standing',NULL,ARRAY['Stand with feet hip-width apart, a slight bend in the knees, and arms at your sides.','Keeping your spine long and neutral, push your hips straight back as if reaching them toward the wall behind you.','Lower your torso toward the floor, feeling a stretch in the hamstrings, while keeping your back flat.','Do not round your lower back - maintain the natural curve of the spine throughout.','When you feel a firm hamstring stretch, reverse the movement by driving your hips forward to return to standing.','Focus on the hip hinge pattern, not depth - go only as far as you can while keeping your back neutral.']::text[]),
('WU000018','Lateral Band Walk','reps_only','glutes',ARRAY['quadriceps']::text[],true,'resistance_band','band lateral walk',NULL,ARRAY['Secure a resistance band around both legs just above the ankles.','Stand with feet hip-width apart, knees slightly bent, in an athletic stance.','Step your right foot to the right, maintaining tension in the band.','Follow with your left foot, bringing it back to hip-width but not allowing the band to go slack.','Continue stepping laterally in one direction for the prescribed reps or distance.','Reverse direction and repeat the same number of steps to the other side.']::text[]),
('WU000019','Terminal Knee Extension (Band)','reps_only','quadriceps',NULL,true,'resistance_band','band extension knee terminal',NULL,ARRAY['Anchor a resistance band just above knee height around a fixed structure.','Stand facing the anchor, loop the band around the back of your right knee, and step back to create tension.','Flex your right knee slightly to begin the movement.','From the slightly bent position, straighten the knee fully, pressing against the band''s resistance.','Hold the fully extended position for a moment, squeezing the quadriceps.','Slowly allow the knee to return to the slightly bent start position and repeat for all reps before switching legs.']::text[]),
('WU000020','Wall Sit (Short Arc Hold)','duration','quadriceps',NULL,true,'none','arc hold short sit wall','0624',ARRAY['Stand with your back flat against a wall and feet about two feet in front of you.','Slide your back down the wall until your hips and knees are both at 90-degree angles.','Keep your feet flat on the floor, shoulder-width apart, with weight evenly distributed.','Hold your arms comfortably at your sides or lightly resting on your thighs.','Maintain the position for the prescribed duration, keeping your back in contact with the wall.','If your knees ache, try a shallower angle - you do not need to reach 90 degrees to get the benefit.']::text[]),
('WU000021','Step-Up Low Box','reps_only','quadriceps',ARRAY['glutes','hamstrings']::text[],true,'none','box low stepup',NULL,ARRAY['Stand in front of a low box or step, no higher than 6 to 8 inches.','Place your right foot fully on the box, ensuring your entire foot is on the surface.','Drive through your right heel to step up, bringing your left foot to meet the right on the box.','Step your left foot back down to the floor, followed by your right foot.','Alternate the leading leg each rep, or complete all reps on one side before switching.','Keep your torso upright throughout and avoid pushing off the back foot to initiate the movement.']::text[]),
('WU000022','Straight Leg Raise','reps_only','quadriceps',ARRAY['abdominals']::text[],true,'none','leg raise straight',NULL,ARRAY['Lie flat on your back with your left knee bent and left foot flat on the floor.','Keep your right leg straight and flex your right foot so toes point toward the ceiling.','Brace your core and slowly raise your right leg to approximately the height of your left knee.','Pause briefly at the top, keeping the quadriceps contracted.','Lower the leg slowly and under control back to the floor.','Complete all reps on the right leg, then switch, bending the right knee and raising the left straight leg.']::text[]),
('WU000023','Calf Raises (Slow)','reps_only','quadriceps',NULL,true,'none','calf raises slow','0605',ARRAY['Stand with feet hip-width apart, hands lightly resting on a wall or chair for balance if needed.','Push through the balls of both feet to rise up onto your toes as high as possible.','Pause at the top for a full second, squeezing the calf muscles.','Lower your heels slowly and with complete control over three to four counts.','Keep the movement smooth and avoid bouncing at the bottom.','Ensure you achieve full range of motion - letting the heels drop slightly below the level of the toes if standing on a step.']::text[]),
('WU000024','Mini Squat (Quarter Squat)','reps_only','quadriceps',ARRAY['glutes']::text[],true,'none','mini quarter squat','5215',ARRAY['Stand with feet hip-width apart, toes pointed slightly outward, and arms at your sides.','Brace your core lightly and keep your chest tall and upright.','Bend at the hips and knees simultaneously to lower to approximately a quarter of a full squat depth.','Ensure your knees track over your toes and your heels remain flat on the floor.','Pause briefly at the bottom, then press through both heels to return to standing.','Focus on a controlled, pain-free movement - do not push into any depth that causes discomfort.']::text[]),
('WU000025','Prone Hamstring Curl (Band)','reps_only','hamstrings',NULL,true,'resistance_band','band curl hamstring prone',NULL,ARRAY['Anchor a resistance band around a fixed point at floor level.','Lie face down on the floor with the band looped around your right ankle.','Keep your hips pressed into the floor and your right thigh in contact with the floor throughout.','Slowly bend your right knee, curling your heel toward your glute against the band''s resistance.','Pause at the top of the curl, squeezing the hamstring for a moment.','Lower the foot slowly back to the floor under control and repeat for all reps before switching legs.']::text[]),
('WU000026','External Rotation with Band','reps_only','shoulders',NULL,true,'resistance_band','band external rotation',NULL,ARRAY['Anchor a resistance band at elbow height around a fixed point.','Stand sideways to the anchor with your right side closest to it.','Hold the band in your right hand with your upper arm pressed against your side, elbow bent to 90 degrees.','Rotate your forearm away from your body, moving your hand outward while keeping the elbow pinned.','Hold at the end range for a moment, feeling the rear shoulder muscles engage.','Return slowly to the start position and complete all reps before switching to the left arm.']::text[]),
('WU000027','Internal Rotation with Band','reps_only','shoulders',NULL,true,'resistance_band','band internal rotation',NULL,ARRAY['Anchor a resistance band at elbow height around a fixed point.','Stand sideways to the anchor with your left side closest to it.','Hold the band in your right hand with your upper arm against your side and elbow bent to 90 degrees.','Rotate your forearm inward, moving your hand across your body while keeping the elbow pinned.','Hold at the end range briefly, feeling the front of the shoulder and subscapularis engage.','Return slowly to the start position and complete all reps before switching to the left arm facing the other direction.']::text[]),
('WU000028','Shoulder Pendulum (Codman''s Exercise)','duration','shoulders',NULL,true,'none','codmans exercise pendulum shoulder',NULL,ARRAY['Stand next to a table or sturdy surface, and lean forward to rest your uninvolved hand on the surface for support.','Let your injured or target arm hang freely and completely relaxed toward the floor.','Using a gentle swaying of your body or a small leg movement, create a pendulum-like swinging motion in the arm.','Allow the arm to swing in small circles - first clockwise, then counterclockwise.','Keep the arm completely passive, using momentum rather than muscle activation.','Gradually increase the diameter of the circles only if it remains pain-free.']::text[]),
('WU000029','Wall Slides','reps_only','shoulders',ARRAY['upper_back','traps']::text[],true,'none','slides wall',NULL,ARRAY['Stand facing a smooth wall with your elbows bent and forearms resting on the wall at shoulder height.','Your elbows and wrists should be in contact with the wall throughout the movement.','Slowly slide both arms up the wall by extending your elbows, keeping forearms and backs of hands against the wall.','Raise your arms as high as you can without losing contact with the wall or arching your lower back.','Pause at the top, then slide slowly back down to the starting position.','Move with control and avoid shrugging your shoulders toward your ears.']::text[]),
('WU000030','Scapular Retraction and Depression','reps_only','upper_back',ARRAY['traps','shoulders']::text[],true,'none','and depression retraction scapular',NULL,ARRAY['Sit or stand tall with your arms resting at your sides and shoulders relaxed.','Begin by drawing both shoulder blades together toward your spine - this is retraction.','From the retracted position, pull both shoulder blades down away from your ears - this is depression.','Hold the combined retraction and depression for two to three seconds.','Slowly release, allowing the shoulder blades to slide back to their resting position.','Focus on feeling the mid and lower trapezius muscles working throughout.']::text[]),
('WU000031','Shoulder CARs (Controlled Articular Rotations)','reps_only','shoulders',NULL,true,'none','cars controlled articular rotations shoulder','5213',ARRAY['Stand or sit tall with your right arm hanging at your side.','Begin to move your right shoulder through a full, slow circular rotation - forward, up, back, and down.','Keep the movement smooth and controlled, exploring the end range in all directions.','Move deliberately through any stiff areas without forcing the joint.','Complete the full circle and then reverse the direction for the same number of reps.','Perform on the left shoulder and aim for maximum range of motion while staying pain-free.']::text[]),
('WU000032','Face Pull (Band)','reps_only','shoulders',ARRAY['upper_back','traps']::text[],true,'resistance_band','band face pull','0233',ARRAY['Anchor a resistance band at approximately face height around a fixed structure.','Stand facing the anchor, holding one end of the band in each hand with a neutral grip.','Step back to create tension in the band with your arms extended.','Pull both handles toward your face by drawing your elbows back and out to the sides.','At the peak of the movement, externally rotate your wrists so your thumbs point behind you.','Slowly return to the starting position with full arm extension and repeat.']::text[]),
('WU000033','Thoracic Spine Rotation','reps_only','upper_back',ARRAY['shoulders']::text[],true,'none','rotation spine thoracic','5216',ARRAY['Sit on the floor or kneel in a tall upright position with arms crossed across your chest.','Keep your lower body and hips still as you rotate your upper back to the right.','Rotate only through the thoracic spine - imagine your ribcage turning while your pelvis stays anchored.','Hold the rotated position for a breath, feeling the stretch along the side of your spine.','Return to center, then rotate to the left for the same hold.','Focus on rotating through the middle and upper back, not the lower back or hips.']::text[]),
('WU000034','Ankle Alphabet','reps_only','full_body',NULL,true,'none','alphabet ankle','5214',ARRAY['Sit in a chair or on the edge of a surface with your right foot lifted off the floor.','Keep the ankle relaxed and begin tracing each letter of the alphabet in the air using only your ankle and foot.','Make the letters as large and distinct as possible to maximize ankle mobility work.','Move slowly and deliberately, especially in directions that feel stiff.','Complete the full alphabet on the right ankle, then switch to the left.','This exercise is particularly useful for improving proprioception after ankle sprains.']::text[]),
('WU000035','Ankle Circles','reps_only','full_body',NULL,true,'none','ankle circles',NULL,ARRAY['Sit in a chair or stand with your right foot slightly raised off the floor.','Keeping your leg still from the knee up, rotate your foot slowly in a clockwise direction.','Draw as large a circle as comfortable, moving through the full available ankle range of motion.','Complete the prescribed number of circles clockwise, then reverse to counterclockwise.','Switch to the left ankle and repeat the same number of circles in each direction.','Focus on slow, smooth motion and gently push into any stiff areas.']::text[]),
('WU000036','Single-Leg Balance','duration','full_body',NULL,true,'none','balance leg single',NULL,ARRAY['Stand near a wall or sturdy surface for safety if needed.','Shift your weight onto your right foot, keeping a very slight bend in the knee.','Lift your left foot off the floor and hold the single-leg stance for the prescribed duration.','Keep your gaze fixed on a still point ahead of you to help maintain balance.','Engage your core and keep your standing hip level - avoid leaning to one side.','Once comfortable, progress the challenge by closing your eyes or standing on an unstable surface.']::text[]),
('WU000037','Banded Ankle Dorsiflexion Mobilisation','duration','full_body',NULL,true,'resistance_band','ankle banded dorsiflexion mobilisation','5210',ARRAY['Anchor a resistance band around a fixed object at floor level.','Sit on the floor facing the anchor with the band looped around the front of your right ankle.','Pull your foot back slightly to create tension in the band, which will pull the ankle forward.','Keep your foot flat and relax, allowing the band to pull the ankle into dorsiflexion.','Hold the mobilised position for the prescribed duration, breathing deeply.','Switch the band to the left ankle and repeat for the same duration.']::text[]),
('WU000038','Heel-to-Toe Rocking','reps_only','full_body',NULL,true,'none','heeltotoe rocking',NULL,ARRAY['Stand with feet hip-width apart and arms at your sides or lightly touching a wall for balance.','Slowly shift your weight forward onto the balls and toes of your feet, lifting your heels as high as comfortable.','Pause briefly at the front, then slowly rock weight back onto your heels, lifting your toes off the floor.','Pause at the rear position, then smoothly roll forward again.','Keep the movement slow and controlled, exploring the end range in both directions.','Breathe steadily throughout, using this movement to mobilise the entire foot and ankle.']::text[]),
('WU000039','Lateral Step-Over','reps_only','glutes',ARRAY['quadriceps']::text[],true,'none','lateral stepover',NULL,ARRAY['Stand alongside a low obstacle such as a cone, foam roller, or small step.','Shift your weight onto your right foot with a slight bend in the knee.','Lift your left leg and step it laterally over the obstacle, clearing it fully.','Follow with your right foot so you are standing on the other side of the obstacle.','Reverse the movement, stepping your right leg back over the obstacle, followed by the left.','Keep your core engaged, hips level, and avoid leaning excessively to either side throughout.']::text[])
ON CONFLICT (id) DO NOTHING;
